import {
  Candidate,
  CreateCandidateRequest,
  CreateNoteRequest,
  Note,
  NotesApiResponse,
  PatchCandidateRequest,
  RecordsApiResponse,
  UpdateCandidateRequest,
} from "@/types/candidate";

const API_URL = process.env.NEXT_PUBLIC_API_URL ?? "https://playground.4geeks.com/tracker/api/v1";

class ApiError extends Error {
  status: number;

  constructor(message: string, status: number) {
    super(message);
    this.name = "ApiError";
    this.status = status;
  }
}

async function apiRequest<T>(path: string, init?: RequestInit): Promise<T> {
  const response = await fetch(`${API_URL}${path}`, {
    ...init,
    headers: {
      "Content-Type": "application/json",
      ...(init?.headers ?? {}),
    },
    cache: "no-store",
  });

  if (!response.ok) {
    let errorMessage = `Error ${response.status}`;

    try {
      const errorBody = await response.json();
      if (typeof errorBody?.error === "string") {
        errorMessage = errorBody.error;
      } else if (typeof errorBody?.detail === "string") {
        errorMessage = errorBody.detail;
      } else if (Array.isArray(errorBody?.detail)) {
        errorMessage = errorBody.detail.map((item: { msg?: string }) => item.msg).filter(Boolean).join(". ");
      }
    } catch {
      // Ignore JSON parsing errors and keep the HTTP status fallback message.
    }

    throw new ApiError(errorMessage, response.status);
  }

  if (response.status === 204) {
    return undefined as T;
  }

  return response.json() as Promise<T>;
}

export async function getRecords(): Promise<Candidate[]> {
  const payload = await apiRequest<RecordsApiResponse>("/records");
  return payload.data;
}

export async function getRecordById(id: string): Promise<Candidate> {
  return apiRequest<Candidate>(`/records/${id}`);
}

export async function createRecord(data: CreateCandidateRequest): Promise<Candidate> {
  return apiRequest<Candidate>("/records", {
    method: "POST",
    body: JSON.stringify(data),
  });
}

export async function updateRecord(id: string, data: UpdateCandidateRequest): Promise<Candidate> {
  return apiRequest<Candidate>(`/records/${id}`, {
    method: "PUT",
    body: JSON.stringify(data),
  });
}

export async function patchRecord(id: string, data: PatchCandidateRequest): Promise<Candidate> {
  return apiRequest<Candidate>(`/records/${id}`, {
    method: "PATCH",
    body: JSON.stringify(data),
  });
}

export async function getRecordNotes(id: string): Promise<Note[]> {
  const payload = await apiRequest<NotesApiResponse>(`/records/${id}/notes`);
  return payload.data;
}

export async function createRecordNote(id: string, data: CreateNoteRequest): Promise<Note> {
  return apiRequest<Note>(`/records/${id}/notes`, {
    method: "POST",
    body: JSON.stringify(data),
  });
}

export async function deleteRecordNote(id: string, noteId: string): Promise<void> {
  await apiRequest<void>(`/records/${id}/notes/${noteId}`, {
    method: "DELETE",
  });
}

export { ApiError };
